const VIEW = { full: "-327.63 -293.72 1681.27 1681.27", header: "-297.3 -293.6 1621.2 1621.2" };

/**
 * The mark, as the contract reads it. Only the orbit is paced by the turn, so only the orbit's
 * phase is carried across a change. The colours change with the state, which is what survives
 * reduced motion.
 */
const SPEC: MarkSpec = {
  id: "glass-front",
  beads: 8,
  paced: /^ch-[tnf]$/,
  liveClass: "cm-live",
  look: {
    rest: { "--ch-c0": "oklch(0.5 0.045 25)", "--ch-c1": "oklch(0.63 0.05 75)", "--ch-c2": "oklch(0.46 0.045 262)", "--ch-shine": "0.18" },
    live: { "--ch-c0": "oklch(0.56 0.21 25)", "--ch-c1": "oklch(0.8 0.16 75)", "--ch-c2": "oklch(0.52 0.19 262)", "--ch-shine": "0.8" },
  },
  turnVar: "--ch-turn",
  paperVar: "--ch-paper",
  view: VIEW,
};

export type GlassFrontMarkProps = MarkProps;

export function GlassFrontMark(props: GlassFrontMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `ch${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "ch-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
